ownedContracts.interfaceSketch:
type IdeKind = 'idea' | 'pycharm' | 'goland' | 'webstorm';
interface ProjectContext {
  readonly projectRootPath: string; // absolute active-project root; the explicit repo argument (k3)
  readonly ide: IdeKind;
}
interface PluginLifecycle {
  onProjectOpened(ctx: ProjectContext): void; // fired once per opened project window
  onPluginUninstalled(): void;                // distinct from a mere disable
}

type DaemonState = 'absent' | 'stale' | 'current';
interface RegistrationResult { readonly registered: boolean; readonly reason?: string; }
interface DaemonGateway {
  probe(): DaemonState;                                    // read-only presence/staleness
  isProjectRegistered(projectRootPath: string): boolean;   // never auto-allocates (k2)
  registerProject(projectRootPath: string): RegistrationResult; // explicit repo.add only
}
